-- ============================================================================
-- Sleeper's Tomb 1.0 -- instanced classic (Al'Kabor/Quarm) expedition, zone
-- shortname 'sleeper', instance version 1 (cazicthule-style).
--
-- Layout is the authentic Quarm/Al'Kabor sleeper population (66 spawns).
-- The 2.0 revamp content in version 0 is NOT modified; all inserts are additive.
-- Class-population NPCs are reused from the existing PEQ rows; only the four
-- Warders, The Sleeper and the missing A_warning are cloned so the warders can
-- carry the classic 'Warders of The Claw' (faction 472) primary faction.
--
-- Id ranges used (verified free at time of writing):
--   npc_types        1520000001-1520000006 (clones), 1520000010 (gatekeeper)
--   npc_faction      1520000001 (+ entries)
--   spawngroup       1520000100+ (one per npc type), 1520000990 (gatekeeper)
--   spawn2           1520000200+ (version 1), 1520000990 (gatekeeper, version 0)
--   grid/grid_entries 1520000000 (awakened-Kerafyrm walk, type 6)
--
-- Import:  mysql -u <user> -p peq < sleeper_1_0.sql
-- ============================================================================

BEGIN;

-- ---------------------------------------------------------------------------
-- 1) Warder faction: primary faction 472 'Warders of The Claw' (base 0 ->
--    indifferent until the sleep-wake event forces aggro).
-- ---------------------------------------------------------------------------
INSERT INTO npc_faction (id, name, primaryfaction, ignore_primary_assist) VALUES
 (1520000001,'sleeper_1_0_warders',472,0);
INSERT INTO npc_faction_entries (npc_faction_id, faction_id, value, npc_value, temp) VALUES
 (1520000001,472,0,0,0);

-- ---------------------------------------------------------------------------
-- 2) Clones (temp LIKE-copy of the existing PEQ row, then override).
-- ---------------------------------------------------------------------------
CREATE TEMPORARY TABLE sleeper_npc_tmp LIKE npc_types;

-- #Nanzata_the_Warder (classic 128090 -> 1520000001)
INSERT INTO sleeper_npc_tmp SELECT * FROM npc_types WHERE id=128090;
UPDATE sleeper_npc_tmp SET id=1520000001, name='#Nanzata_the_Warder', npc_faction_id=1520000001;
INSERT INTO npc_types SELECT * FROM sleeper_npc_tmp;
DELETE FROM sleeper_npc_tmp;

-- #Ventani_the_Warder (classic 128091 -> 1520000002)
INSERT INTO sleeper_npc_tmp SELECT * FROM npc_types WHERE id=128091;
UPDATE sleeper_npc_tmp SET id=1520000002, name='#Ventani_the_Warder', npc_faction_id=1520000001;
INSERT INTO npc_types SELECT * FROM sleeper_npc_tmp;
DELETE FROM sleeper_npc_tmp;

-- #Tukaarak_the_Warder (classic 128092 -> 1520000003)
INSERT INTO sleeper_npc_tmp SELECT * FROM npc_types WHERE id=128092;
UPDATE sleeper_npc_tmp SET id=1520000003, name='#Tukaarak_the_Warder', npc_faction_id=1520000001;
INSERT INTO npc_types SELECT * FROM sleeper_npc_tmp;
DELETE FROM sleeper_npc_tmp;

-- #Hraashna_the_Warder (classic 128093 -> 1520000004)
INSERT INTO sleeper_npc_tmp SELECT * FROM npc_types WHERE id=128093;
UPDATE sleeper_npc_tmp SET id=1520000004, name='#Hraashna_the_Warder', npc_faction_id=1520000001;
INSERT INTO npc_types SELECT * FROM sleeper_npc_tmp;
DELETE FROM sleeper_npc_tmp;

-- #The_Sleeper (classic 128094 -> 1520000005)
INSERT INTO sleeper_npc_tmp SELECT * FROM npc_types WHERE id=128094;
UPDATE sleeper_npc_tmp SET id=1520000005, name='#The_Sleeper', npc_faction_id=0, bodytype=29;
INSERT INTO npc_types SELECT * FROM sleeper_npc_tmp;
DELETE FROM sleeper_npc_tmp;

-- A_warning (absent from PEQ; clone from A_wardstone donor 128074)
INSERT INTO sleeper_npc_tmp SELECT * FROM npc_types WHERE id=128074;
UPDATE sleeper_npc_tmp SET id=1520000006, name='A_warning', level=60, hp=19000, race=127, class=1, bodytype=65, npc_faction_id=0, loottable_id=0;
INSERT INTO npc_types SELECT * FROM sleeper_npc_tmp;
DELETE FROM sleeper_npc_tmp;

-- Sleeper's Tomb Gatekeeper (cloned from Echo_of_the_Past 1120000940 -> 1520000010)
INSERT INTO sleeper_npc_tmp SELECT * FROM npc_types WHERE id=1120000940;
UPDATE sleeper_npc_tmp SET id=1520000010, name='Sleeper_Tomb_Gatekeeper', level=65, loottable_id=0, npc_faction_id=0, npc_spells_id=0, runspeed=1.25, raid_target=0, bodytype=7;
INSERT INTO npc_types SELECT * FROM sleeper_npc_tmp;
DELETE FROM sleeper_npc_tmp;

DROP TEMPORARY TABLE sleeper_npc_tmp;

